<?php
 namespace App; use App\Library\Helper; use App\Model_ as Model; class Category extends Model { protected $guarded = []; function getUrlAttribute() { return config('app.url') . '/c/' . Helper::id_encode($this->id, Helper::ID_TYPE_CATEGORY); } function products() { return $this->hasMany(Product::class); } function user() { return $this->belongsTo(User::class); } function getTmpPassword() { return md5('$wGgMd45Jgi@dBDR' . $this->password . '1#DS2%!VLqJolmMD'); } function getProductsForShop() { $products = Product::where('category_id', $this->id) ->where('enabled', 1) ->orderBy('sort') ->get(); foreach ($products as $product) { $product->setForShop($this->user); }; $this->makeVisible(['products']); $this->setAttribute('products', $products); return $products; } } 